<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Academy directory · MSZ ERP</title><link rel="stylesheet" href="{{ asset('css/academy.css') }}"></head><body class="print-page"><header class="print-toolbar"><a href="{{ route('superadmin.academies') }}">← Back to academies</a><button onclick="window.print()">Print directory</button></header><main class="print-document"><header class="print-document-heading"><div><span>MSZ ERP · PLATFORM DIRECTORY</span><h1>Academies</h1><p>Search: “{{ $search }}”</p></div><div><strong>{{ $academies->count() }}</strong><small>matching academies</small></div></header><table class="print-table"><thead><tr><th>Academy</th><th>City / province</th><th>Contact</th><th>Administrator</th><th>Enabled options</th><th>Status</th></tr></thead><tbody>@foreach ($academies as $academy)<tr><td>{{ $academy->name }} · {{ $academy->slug }}</td><td>{{ collect([$academy->city, $academy->province])->filter()->implode(', ') ?: '—' }}</td><td>{{ $academy->contact_email ?: $academy->contact_phone ?: '—' }}</td><td>{{ $academy->administrator?->name ?? 'No admin' }} · {{ $academy->administrator?->email ?? '' }}</td><td>{{ count($academy->enabled_features ?? []) }}</td><td>{{ $academy->is_active ? 'Active' : 'Suspended' }}</td></tr>@endforeach</tbody></table></main><script>window.addEventListener('load',()=>window.print());</script></body></html>
